input.command:
python3 - <<'EOF'
import re
s=open('alquimia-web-reactiva.html',encoding='utf-8').read()
js=re.search(r'<script>(.*)</script>',s,re.S).group(1)
open('/tmp/bench-ws/claude-haiku/check_tmp.js','w',encoding='utf-8').write(js)
EOF
node --check /tmp/bench-ws/claude-haiku/check_tmp.js && echo SYNTAX_OK
cat > /tmp/bench-ws/claude-haiku/reach_tmp.js <<'EOF'
const fs=require('fs');
const js=fs.readFileSync('/tmp/bench-ws/claude-haiku/check_tmp.js','utf8');
const get=(name)=>{const m=js.match(new RegExp('const '+name+' = (\\[|\\{)[\\s\\S]*?\\n  (\\]|\\});'));return eval('('+m[0].replace(/^const \w+ = /,'').replace(/;$/,'')+')')};
const E=get('ELEMENTS'); const R=get('RECIPES');
const known=new Set(['codigo','humano','idea','cafe']);
let ch=true; while(ch){ch=false; for(const [a,b,r] of R) if(known.has(a)&&known.has(b)&&!known.has(r)){known.add(r);ch=true;}}
console.log('elements',Object.keys(E).length,'recipes',R.length,'reachable',known.size);
console.log('unreachable:',Object.keys(E).filter(k=>!known.has(k)));
console.log('bad refs:',R.filter(([a,b,r])=>!E[a]||!E[b]||!E[r]));
EOF
node /tmp/bench-ws/claude-haiku/reach_tmp.js; rm -f /tmp/bench-ws/claude-haiku/check_tmp.js /tmp/bench-ws/claude-haiku/reach_tmp.js

